using System.Collections.Generic;
using UnityEngine;

// The size a UI texture was made at (PS Vita port). NGUI keeps sprite, glyph and border rectangles in atlas pixels and
// divides them by the texture's size. On the PS Vita the big UI textures are imported at half size (KFTextureVita: they
// were made for 1920 x 1080 phones, the Vita screen is 960 x 544, and at full 32-bit size the menu and a level's UI
// overflowed video memory), so NGUI asks here instead of reading Texture.width / height. Entries are generated by
// KFTextureVita (KFUISourceSize.Entries.cs); a texture that is not listed, or not at its listed imported size (another
// platform), reports its own size.
public static partial class KFUISourceSize
{
	private struct Entry
	{
		public string Name;

		public int Width;

		public int Height;

		public int SourceWidth;

		public int SourceHeight;

		public Entry(string name, int width, int height, int sourceWidth, int sourceHeight)
		{
			Name = name;
			Width = width;
			Height = height;
			SourceWidth = sourceWidth;
			SourceHeight = sourceHeight;
		}
	}

	private static Dictionary<string, Entry> byName;

	// instance ID -> source size (Texture.name allocates, and NGUI asks every time a sprite changes)
	private static readonly Dictionary<int, Vector2> cache = new Dictionary<int, Vector2>();

	public static int Width(Texture texture)
	{
		return (int)Size(texture).x;
	}

	public static int Height(Texture texture)
	{
		return (int)Size(texture).y;
	}

	private static Vector2 Size(Texture texture)
	{
		if (texture == null)
		{
			return Vector2.zero;
		}
		int id = texture.GetInstanceID();
		Vector2 size;
		if (cache.TryGetValue(id, out size))
		{
			return size;
		}
		if (byName == null)
		{
			byName = new Dictionary<string, Entry>();
			foreach (Entry e in Entries)
			{
				byName[e.Name] = e;
			}
		}
		Entry entry;
		size = byName.TryGetValue(texture.name, out entry) && texture.width == entry.Width && texture.height == entry.Height
			? new Vector2(entry.SourceWidth, entry.SourceHeight)
			: new Vector2(texture.width, texture.height);
		cache[id] = size;
		return size;
	}
}
